use super::*;
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
use util::org::apache::poi::util::LittleEndianByteArrayOutput::LittleEndianByteArrayOutput;
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
fn one(p:&Value)->Value{let raw=p["bytes"].as_str().map(|s|Rc::new(RefCell::new((0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect::<Vec<_>>().into_boxed_slice())));let mut value=None;let mut row=call(||{value=match p["kind"].as_str().unwrap(){"bits"=>SpecialCachedValue::create__bits(u64::from_str_radix(p["bits"].as_str().unwrap(),16).unwrap()as i64),"error"=>Some(SpecialCachedValue::createCachedErrorCode(p["value"].as_i64().unwrap()as i32)),"boolean"=>Some(SpecialCachedValue::createCachedBoolean(p["value"].as_bool().unwrap())),"string"=>Some(SpecialCachedValue::createForString()),"empty"=>Some(SpecialCachedValue::createCachedEmptyValue()),_=>Some(Rc::new(SpecialCachedValue::new(raw.clone())))};});row["null"]=json!(value.is_none());if let Some(v)=value{if p["mutate"]==true{raw.as_ref().unwrap().borrow_mut()[0]=1;}row["getTypeCode"]=call(||v.getTypeCode());row["getDataValue"]=call(||v.getDataValue());row["getValueType"]=call(||v.getValueType());row["getBooleanValue"]=call(||v.getBooleanValue());row["getErrorValue"]=call(||v.getErrorValue());row["formatDebugString"]=call(||v.formatDebugString());row["toString"]=call(||v.toString());let mut bytes=LittleEndianByteArrayOutput::new();row["serialize"]=call(||v.serialize(&mut bytes));row["bytes"]=json!(bytes.get_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>());}row}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_formula_record_special_cached_values(){let root=std::path::PathBuf::from(std::env::var("SS_CORE_PROOF_ROOT").unwrap_or_else(|_|env!("CARGO_MANIFEST_DIR").into()));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/cell-record-r0b65");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!(input["special"].as_array().unwrap().iter().map(one).collect::<Vec<_>>());std::fs::write(p.join("rust-special.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java["special"],"special");}
